import fs from "node:fs/promises";
import path from "node:path";
import sharp from "sharp";

// Artwork is generated by ImageGen; QR modules remain the verified local SVG.
const folder = path.resolve("public/dedications/faculty-20-10");
const art = await fs.readFile(path.join(folder, "chibi-cac-co.png"));
const qr = await fs.readFile(path.join(folder, "ma-qr-thiep-20-10.svg"));
const data = (mime, buffer) =>
  `data:${mime};base64,${buffer.toString("base64")}`;
const poster = `<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="2264" viewBox="0 0 1600 2264">
<defs>
  <linearGradient id="paper" x2="0" y2="1"><stop stop-color="#fffaf3"/><stop offset=".5" stop-color="#fff3ef"/><stop offset="1" stop-color="#fce9ec"/></linearGradient>
  <radialGradient id="halo"><stop stop-color="#f5d6d9" stop-opacity=".65"/><stop offset="1" stop-color="#f5d6d9" stop-opacity="0"/></radialGradient>
</defs>
<rect width="1600" height="2264" fill="url(#paper)"/>
<ellipse cx="800" cy="820" rx="740" ry="560" fill="url(#halo)"/>
<rect x="42" y="42" width="1516" height="2180" rx="55" fill="none" stroke="#d9acb4" stroke-width="2"/>
<rect x="57" y="57" width="1486" height="2150" rx="44" fill="none" stroke="#efd7d4" stroke-width="2"/>
<g text-anchor="middle" font-family="Segoe UI,Arial,sans-serif">
  <text x="800" y="139" font-size="24" letter-spacing="6" fill="#9a6e70">MỘT MÓN QUÀ NHỎ · NGÀN LỜI YÊU THƯƠNG</text>
  <text x="800" y="309" font-family="Georgia,serif" font-size="164" fill="#7e4156">20 · 10</text>
  <text x="800" y="385" font-size="46" font-weight="600" fill="#593e49">Kính tặng các Cô</text>
  <text x="800" y="440" font-size="30" fill="#8f6670">Khoa Tin học và Ngoại ngữ</text>
</g>
<image href="${data("image/png", art)}" x="88" y="478" width="1424" height="650" preserveAspectRatio="xMidYMid meet"/>
<g fill="#ac7788"><circle cx="650" cy="1155" r="3"/><circle cx="950" cy="1155" r="3"/></g>
<path d="M679 1155H763M837 1155H921" stroke="#cfa5ac" stroke-width="1.5"/>
<text x="800" y="1165" text-anchor="middle" font-family="Segoe UI Symbol,Arial" font-size="31" fill="#b76d85">♡</text>
<rect x="350" y="1200" width="900" height="900" rx="46" fill="#ffffff" stroke="#ead2d5" stroke-width="2"/>
<image href="${data("image/svg+xml", qr)}" x="383" y="1233" width="834" height="834"/>
<g text-anchor="middle" font-family="Segoe UI,Arial,sans-serif">
  <text x="800" y="2150" font-size="29" font-weight="600" fill="#7e4156">Quét mã để nhận một bó hoa và ngàn lời chúc</text>
  <text x="800" y="2193" font-size="19" letter-spacing="1" fill="#a77d87">Chúc các Cô luôn rạng rỡ, bình an và hạnh phúc ♡</text>
</g>
</svg>`;
await fs.writeFile(path.join(folder, "bang-qr-20-10-chibi.svg"), poster);
await sharp(Buffer.from(poster))
  .png()
  .withMetadata({ density: 300 })
  .toFile(path.join(folder, "bang-qr-20-10-chibi.png"));
await sharp(art)
  .resize({ width: 1400, withoutEnlargement: true })
  .webp({ quality: 90 })
  .toFile(path.join(folder, "chibi-cac-co.webp"));
console.log(
  "Chibi poster ready: 1600 × 2264 px, 300 DPI metadata; QR links to /20-10.",
);
